const cbQuery = $input.first().json.callback_query;
if (!cbQuery) return [];

const cbData   = cbQuery.data || '';
const fromUser = cbQuery.from || {};
const msg      = cbQuery.message || {};
const messageId = msg.message_id;
const chatId    = String(msg.chat?.id || '-5006780541');
const queryId   = cbQuery.id;
const plainText = msg.text || '';

// اسم من ضغط الزر
const presserName = (fromUser.first_name || '') +
  (fromUser.last_name ? ' ' + fromUser.last_name : '');

// إعادة بناء HTML من النص العادي
function toHtml(text) {
  const lines = text.split('\n');
  return lines.map((line, i) => {
    if (i === 0) return '<b>' + line + '</b>'; // السطر الأول دائماً عريض
    // أضف bold للحقول: emoji + نص + نقطتين
    return line.replace(
      /^([\p{Emoji_Presentation}\p{Extended_Pictographic}\u200d]+\s*)([^:]+:)/u,
      '$1<b>$2</b>'
    );
  }).join('\n');
}

let htmlText = toHtml(plainText);
let newReplyMarkup;
let action = cbData;

if (cbData === 'take_design') {
  // استبدل سطر الحالة
  htmlText = htmlText.replace(
    /⏳ <b>الحالة:<\/b> بانتظار استلام مصمم\.\.\./,
    `⏳ <b>الحالة:</b> 👨‍🎨 قيد التصميم بواسطة: ${presserName}`
  );
  if (!htmlText.includes('قيد التصميم')) {
    // fallback: استبدل آخر سطر يحتوي كلمة الحالة
    const lines = htmlText.split('\n');
    for (let i = lines.length - 1; i >= 0; i--) {
      if (lines[i].includes('الحالة')) {
        lines[i] = `⏳ <b>الحالة:</b> 👨‍🎨 قيد التصميم بواسطة: ${presserName}`;
        break;
      }
    }
    htmlText = lines.join('\n');
  }
  // أبقِ زر التجهيز فقط
  newReplyMarkup = { inline_keyboard: [[{ text: '📦 تم التجهيز', callback_data: 'order_ready' }]] };

} else if (cbData === 'order_ready') {
  const lines = htmlText.split('\n');
  for (let i = lines.length - 1; i >= 0; i--) {
    if (lines[i].includes('الحالة')) {
      lines[i] = `✅ <b>الحالة:</b> تم التجهيز والتسليم للتوصيل بواسطة: ${presserName}`;
      break;
    }
  }
  htmlText = lines.join('\n');
  newReplyMarkup = { inline_keyboard: [] }; // حذف جميع الأزرار

} else {
  return []; // callback غير معروف
}

// body إجابة Callback (لإخفاء التحميل)
const answerBody = JSON.stringify({ callback_query_id: queryId });

// body تعديل الرسالة
const editBody = JSON.stringify({
  chat_id:    chatId,
  message_id: messageId,
  text:       htmlText,
  parse_mode: 'HTML',
  reply_markup: newReplyMarkup
});

return [{ json: { queryId, chatId, messageId, answerBody, editBody, action } }];
